let siteFeatureSettings=null;async function loadSiteFeatures(){try{const r=await fetch('/api/site-management',{credentials:'same-origin'});if(!r.ok)return;const d=await r.json();siteFeatureSettings=d;if(typeof state!=='undefined'){state.siteManagement={roundHistoryDemo:d.roundHistoryDemo,battleCalcTest:d.battleCalcTest};const lab=document.getElementById('uplinkTestLab');if(lab)lab.hidden=!d.battleCalcTest;}const panel=document.querySelector('[data-staff-section="news"]');if(panel&&d.canEdit&&!document.getElementById('siteTestFeatures')){const module=document.createElement('section');module.id='siteTestFeatures';module.className='profile-theme-box';module.innerHTML='<h3>Site test features</h3><p>These switches apply to the entire site. Real archived rounds always replace demonstration rounds.</p><label><input id="historyDemoEnabled" type="checkbox" '+(d.roundHistoryDemo?'checked':'')+'> Show fictional Round history examples while the real archive is empty</label><label><input id="battleTestEnabled" type="checkbox" '+(d.battleCalcTest?'checked':'')+'> Enable the simulated battle lab and battle calculator test</label><button class="button" id="saveSiteTestFeatures">SAVE SITE FEATURES</button><p id="siteFeatureStatus" role="status"></p>';panel.prepend(module);document.getElementById('saveSiteTestFeatures').onclick=saveSiteFeatures;}}catch{}}
async function saveSiteFeatures(){const status=document.getElementById('siteFeatureStatus');try{const r=await fetch('/api/site-management',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:siteFeatureSettings.revision,roundHistoryDemo:document.getElementById('historyDemoEnabled').checked,battleCalcTest:document.getElementById('battleTestEnabled').checked})}),d=await r.json();if(!r.ok)throw Error(d.error||'Save failed.');siteFeatureSettings.revision=d.revision;status.textContent='✓ Site features saved · '+new Date().toLocaleTimeString();}catch(e){status.textContent=e.message;}}
setTimeout(loadSiteFeatures,1000);setInterval(loadSiteFeatures,30000);
